solutions.java:
class Solution {
    public String crackPassword(int[] nums) {
        return Arrays.stream(nums)
            .mapToObj(String::valueOf)
            .sorted((a, b) -> (a + b).compareTo(b + a))
            .collect(Collectors.joining());
    }
}

